import { bigint, date, integer, timestamp, uuid } from 'drizzle-orm/pg-core';

/** Random UUID primary key generated by PostgreSQL. */
export const primaryId = () => uuid('id').primaryKey().defaultRandom();

/** A moment in time, always UTC. */
export const instant = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });

export const createdAt = () => instant('created_at').notNull().defaultNow();
export const updatedAt = () => instant('updated_at').notNull().defaultNow();

/** Optimistic concurrency: updates check the version they read. */
export const version = () => integer('version').notNull().default(1);

/** Money in paise (integer minor units). */
export const money = (name: string) => bigint(name, { mode: 'number' });

/** A calendar date in the business timezone, as `YYYY-MM-DD`. */
export const calendarDate = (name: string) => date(name, { mode: 'string' });
